class Node:
    def __init__(self, val):
        self.val = val
        self.left = self.right = None

def read_tree():
    values = input().split()
    if not values or values[0] == 'null': return None
    root = Node(int(values[0]))
    queue, i = deque([root]), 1
    while queue and i < len(values):
        node = queue.popleft()
        for side in ('left', 'right'):
            if i < len(values) and values[i] != 'null':
                child = Node(int(values[i]))
                setattr(node, side, child)
                queue.append(child)
            i += 1
    return root

def show_tree(root):
    queue, ans = deque([root]), []
    while queue:
        node = queue.popleft()
        if node is None: ans.append('null')
        else:
            ans.append(str(node.val))
            queue.extend((node.left, node.right))
    while len(ans) > 1 and ans[-1] == 'null': ans.pop()
    print(' '.join(ans))

def solve():
    root = read_tree()
    stack, ans, cur = [], [], root
    while cur or stack:
        while cur: stack.append(cur); cur = cur.left
        cur = stack.pop()
        ans.append(cur.val)
        cur = cur.right
    print(*ans) if ans else print('EMPTY')

if __name__ == "__main__":
    solve()

