import sys

def solve():
    n = int(input())
    a = list(map(int, input().split()))
    low=mid=0; high=n-1
    while mid<=high:
        if a[mid]==0:
            a[low],a[mid]=a[mid],a[low]; low+=1; mid+=1
        elif a[mid]==2:
            a[mid],a[high]=a[high],a[mid]; high-=1
        else: mid+=1
    print(*a)

if __name__ == "__main__":
    solve()
